use std::collections::HashMap;
use std::io::{self, Read, Write};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();

    let n: usize = loop {
        match lines.next() {
            Some(l) if !l.trim().is_empty() => break l.trim().parse().unwrap_or(0),
            Some(_) => continue,
            None => return,
        }
    };

    // name -> (manager, salary)
    let mut emp: HashMap<String, (String, String)> = HashMap::new();
    let mut read = 0;
    while read < n {
        match lines.next() {
            Some(l) => {
                let parts: Vec<&str> = l.split_whitespace().collect();
                if parts.len() >= 3 {
                    emp.insert(
                        parts[0].to_string(),
                        (parts[1].to_string(), parts[2].to_string()),
                    );
                    read += 1;
                } else if parts.is_empty() {
                    continue;
                } else {
                    read += 1;
                }
            }
            None => break,
        }
    }

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for l in lines {
        let q = l.trim();
        if q.is_empty() {
            continue;
        }
        let result = match emp.get(q) {
            None => format!("none: unknown {}", q),
            Some((mgr, _)) => {
                if mgr == "-" {
                    format!("none: no manager {}", q)
                } else {
                    match emp.get(mgr.as_str()) {
                        None => format!("none: unknown {}", mgr),
                        Some((mgr2, _)) => {
                            if mgr2 == "-" {
                                format!("none: no skip-level {}", mgr)
                            } else {
                                match emp.get(mgr2.as_str()) {
                                    None => format!("none: unknown {}", mgr2),
                                    Some((_, sal)) => sal.clone(),
                                }
                            }
                        }
                    }
                }
            }
        };
        writeln!(out, "{}", result).unwrap();
    }
}
